#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(svglite)})
B<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/analysis_revisions_20260906";O<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/final_analysis_20260907/Figure6_spatial_mechanistic";dir.create(O,recursive=TRUE,showWarnings=FALSE)
sp<-read.csv(file.path(B,"GSE171351_spatial_validation/GSE171351_spot_scores.csv"));ss<-read.csv(file.path(B,"GSE171351_spatial_validation/GSE171351_spatial_patient_summary.csv"));lr<-read.csv(file.path(B,"CCDC80_LR_myeloid_integration/CCDC80_LR_myeloid_integrated_ranking.csv"));tf<-read.csv(file.path(B,"CellOracle_GSE135337/CCDC80_state_TF_candidate_ranking.csv"))
T<-theme_classic(base_family="Arial",base_size=10)+theme(plot.title=element_text(face="bold",size=11,hjust=0),plot.subtitle=element_text(size=8,colour="#444"),axis.title=element_text(size=9),axis.text=element_text(size=8),axis.line=element_line(linewidth=.4),axis.ticks=element_line(linewidth=.3),panel.grid=element_blank(),legend.position="none",plot.margin=margin(6,10,6,10))
r<-sp[sp$sampleID=="B1",];r$y<-max(r$array_row)-r$array_row;r$ECM_high<-r$ECM_signature>=quantile(r$ECM_signature,.75,na.rm=TRUE);r$MY_high<-r$Myeloid_score>=quantile(r$Myeloid_score,.75,na.rm=TRUE);r$quad<-interaction(r$ECM_high,r$MY_high,drop=TRUE);levels(r$quad)<-c("Low / Low","High ECM / Low myeloid","Low ECM / High myeloid","High / High")
map<-function(d,v,t,sub,cols){ggplot(d,aes(array_col,y,colour=.data[[v]]))+geom_point(size=1.25,alpha=.9)+scale_colour_gradientn(colours=cols)+coord_equal()+labs(title=t,subtitle=sub,x="Array column",y="Array row")+T}
pA<-map(r,"CCDC80","(A) CCDC80 spatial distribution","Representative section: B1 / Bladder8",c("#F2F2F2","#356A8A"))
pB<-ggplot(r,aes(array_col,y,colour=quad))+geom_point(size=1.25,alpha=.9)+scale_colour_manual(values=c("Low / Low"="#D9D9D9","High ECM / Low myeloid"="#6E9CB3","Low ECM / High myeloid"="#D69A62","High / High"="#8B4F57"))+coord_equal()+labs(title="(B) ECM-myeloid co-localization",subtitle="Bivariate top-quartile classification",x="Array column",y="Array row",colour="Spatial state")+T+theme(legend.position="bottom",legend.text=element_text(size=7))
ss$lab<-paste(ss$Patient,"(n=",ss$n_spots,")");ss$lab<-factor(ss$lab,levels=rev(ss$lab));m<-rbind(data.frame(patient=ss$lab,metric="ECM-myeloid",rho=ss$rho_ECM_myeloid,p=ss$p_ECM_myeloid),data.frame(patient=ss$lab,metric="ECM-neighbor myeloid",rho=ss$rho_ECM_neighbor_myeloid,p=ss$p_ECM_neighbor_myeloid));pC<-ggplot(m,aes(rho,patient,colour=metric))+geom_vline(xintercept=0,colour="#777",linewidth=.35)+geom_point(position=position_dodge(width=.45),size=2.5)+scale_colour_manual(values=c("ECM-myeloid"="#356A8A","ECM-neighbor myeloid"="#C98245"))+labs(title="(C) Spatial association across patients",subtitle="Each point is one sample; Spearman rho",x="Spearman rho",y=NULL,colour=NULL)+T+theme(legend.position="bottom")
genes<-c("CCDC80","ECM_signature","Myeloid_score","CSF1","IL6","CXCL12");long<-do.call(rbind,lapply(genes,function(g)data.frame(gene=g,value=r[[g]],array_col=r$array_col,y=r$y)));long$gene<-factor(long$gene,levels=genes);pD<-ggplot(long,aes(array_col,y,colour=value))+geom_point(size=.7)+scale_colour_gradient2(low="#356A8A",mid="white",high="#C98245",midpoint=0)+facet_wrap(~gene,nrow=2)+coord_equal()+labs(title="(D) Spatial ligand and program context",subtitle="Same section; matched coordinates across six features",x="Array column",y="Array row",colour="Score")+T+theme(strip.text=element_text(face="bold",size=8),legend.position="right")
lr<-lr[order(-lr$evidence_score,-lr$mean_LR_potential),];lr<-head(lr,8);lr$pair<-factor(lr$pair,levels=rev(lr$pair));lr$ligand_axis<-lr$rho_ligand_CCDC80;lr$receptor_axis<-lr$rho_receptor_myeloid_score;lr$lr_axis<-lr$rho_LR_myeloid_score;L<-rbind(data.frame(pair=lr$pair,evidence="ligand~CCDC80",value=lr$ligand_axis),data.frame(pair=lr$pair,evidence="receptor~myeloid",value=lr$receptor_axis),data.frame(pair=lr$pair,evidence="LR~myeloid",value=lr$lr_axis));pE<-ggplot(L,aes(evidence,pair,fill=value))+geom_tile(colour="white",linewidth=.6)+geom_text(aes(label=sprintf("%.2f",value)),size=2.5)+scale_fill_gradient2(low="#356A8A",mid="white",high="#C98245",midpoint=0)+labs(title="(E) Candidate communication evidence",subtitle="Integrated LR ranking across 7 patients; prioritization only",x=NULL,y=NULL,fill="Spearman rho")+T+theme(axis.text.x=element_text(angle=25,hjust=1),legend.position="right")
tf<-tf[order(-tf$mean_abs_delta),];tf<-head(tf,10);tf$TF<-factor(tf$source,levels=rev(tf$source));pF<-ggplot(tf,aes(mean_abs_delta,TF,fill=n_supported))+geom_col(width=.65)+geom_text(aes(label=paste0("n=",n_supported)),hjust=-.1,size=2.7)+scale_fill_gradient(low="#B8CBD4",high="#356A8A")+scale_x_continuous(expand=expansion(mult=c(0,.18)))+labs(title="(F) CCDC80-state regulatory candidates",subtitle="CellOracle TF ranking by mean absolute perturbation delta",x="Mean absolute delta across ECM targets",y=NULL,fill="Supported targets")+T+theme(legend.position="right")
fig<-(pA|pB)/(pC|pD)/(pE|pF)+plot_layout(heights=c(1,1.15,1));ggsave(file.path(O,"Figure6_spatial_mechanistic.pdf"),fig,width=240,height=320,units="mm",device=cairo_pdf,bg="white");ggsave(file.path(O,"Figure6_spatial_mechanistic.svg"),fig,width=240,height=320,units="mm",device=svglite,bg="white");ggsave(file.path(O,"Figure6_spatial_mechanistic.tif"),fig,width=240,height=320,units="mm",dpi=600,compression="lzw",device="tiff",bg="white")
write.csv(r,file.path(O,"Figure6_source_representative_spatial.csv"),row.names=FALSE);write.csv(ss,file.path(O,"Figure6_source_spatial_summary.csv"),row.names=FALSE);write.csv(lr,file.path(O,"Figure6_source_LR_top8.csv"),row.names=FALSE);write.csv(tf,file.path(O,"Figure6_source_TF_ranking.csv"),row.names=FALSE)
